     */
    @Deprecated
    public UMLStateDiagram() {
        super(new StateDiagramGraphModel());
        try {
            setName(getNewDiagramName());
        } catch (PropertyVetoException pve) {
            // nothing we can do about veto, so just ignore it
        }
