    /**
     * Determines if the diagram accepts the given object.
     *
     * @param objectToAccept the object to check
     * @return true if the object is accepted
     */
    @Override
    public boolean doesAccept(Object objectToAccept) {
        if (Model.getFacade().isAState(objectToAccept)) {
            return true;
        } else if (Model.getFacade().isASynchState(objectToAccept)) {
            return true;
        } else if (Model.getFacade().isAStubState(objectToAccept)) {
            return true;
        } else if (Model.getFacade().isAPseudostate(objectToAccept)) {
            return true;
        } else if (Model.getFacade().isAComment(objectToAccept)) {
            return true;
        }
        return false;
    }

