    return pt.name


def _add_newbook_tag(mi):
    tags = prefs['new_book_tags']
    if not tags:
        return
    for tag in [t.strip() for t in tags]:
        if not tag:
            continue
        if not mi.tags:
            mi.tags = [tag]
        elif tag not in mi.tags:
            mi.tags.append(tag)


